            // e8 family (hi==8 or lo^hi==8); here lo^hi==9 so only hi==8 is dropped.
            if (lo ^ hi) == 9 && hi != 8 {
                var neg = 0
                while neg <= 1 {
                    if m < 12 {
                        flo[m as usize] = lo
                        fhi[m as usize] = hi
                        fng[m as usize] = neg
                        m = m + 1
                    }
                    neg = neg + 1
                }
            }
            hi = hi + 1
        }
        lo = lo + 1
