use ot::transport_exact::*
use math::rational::*

fn main() -> i64 with Mut, Div, Panic {
    // HP1: masses (2/3,1/3)->(1/3,2/3), cost [[5,1],[1,5]] ; W1 = 1 ; opt=3 (greedy NW=11)
    OT_SNUM[0]=2; OT_SDEN[0]=3; OT_SNUM[1]=1; OT_SDEN[1]=3;
    OT_DNUM[0]=1; OT_DDEN[0]=3; OT_DNUM[1]=2; OT_DDEN[1]=3;
    OT_COST[0]=5; OT_COST[1]=1; OT_COST[2]=1; OT_COST[3]=5;
    let w1 = w1_rational(2,2);
    if w1.num != 1 { return 1; }
    if w1.den != 1 { return 2; }
    // integer opt must be 3 (minimization), NOT the greedy 11
    OT_SUPPLY[0]=2; OT_SUPPLY[1]=1; OT_DEMAND[0]=1; OT_DEMAND[1]=2;
    let ci = w1_int(2,2);
    if ci != 3 { return 30 + ci; }
    // HP2: (1/3,2/3)->(2/3,1/3), cost [[0,1],[1,0]] ; W1 = 1/3
    OT_SNUM[0]=1; OT_SDEN[0]=3; OT_SNUM[1]=2; OT_SDEN[1]=3;
    OT_DNUM[0]=2; OT_DDEN[0]=3; OT_DNUM[1]=1; OT_DDEN[1]=3;
    OT_COST[0]=0; OT_COST[1]=1; OT_COST[2]=1; OT_COST[3]=0;
    let w2 = w1_rational(2,2);
    if w2.num != 1 { return 4; }
    if w2.den != 3 { return 5; }
    // HP3: (3/5,2/5)->(2/5,3/5), cost [[1,4],[4,1]] ; W1 = 8/5
    OT_SNUM[0]=3; OT_SDEN[0]=5; OT_SNUM[1]=2; OT_SDEN[1]=5;
    OT_DNUM[0]=2; OT_DDEN[0]=5; OT_DNUM[1]=3; OT_DDEN[1]=5;
    OT_COST[0]=1; OT_COST[1]=4; OT_COST[2]=4; OT_COST[3]=1;
    let w3 = w1_rational(2,2);
    if w3.num != 8 { return 6; }
    if w3.den != 5 { return 7; }
    return 0;
}

//@ run-pass
// Tests for logic laws: De Morgan, double negation, contraposition
// Validates mathematical properties directly (no theorem prover framework needed)

fn main() -> i32 with IO, Mut, Panic {
    var pass = 0
    var fail = 0

    // Test 1: or_comm — P \/ Q == Q \/ P (all 4 combinations)
    var t1 = true
    var p = false; var q = false
    if (p || q) != (q || p) { t1 = false }
    p = true; q = false
    if (p || q) != (q || p) { t1 = false }
    p = false; q = true
    if (p || q) != (q || p) { t1 = false }
    p = true; q = true
    if (p || q) != (q || p) { t1 = false }
    if t1 { pass = pass + 1; println("PASS T1: or_comm") }
    else { fail = fail + 1; println("FAIL T1: or_comm") }

    // Test 2: and_comm
    var t2 = true
    p = false; q = false
    if (p && q) != (q && p) { t2 = false }
    p = true; q = false
    if (p && q) != (q && p) { t2 = false }
    p = false; q = true
    if (p && q) != (q && p) { t2 = false }
    p = true; q = true
    if (p && q) != (q && p) { t2 = false }
    if t2 { pass = pass + 1; println("PASS T2: and_comm") }
    else { fail = fail + 1; println("FAIL T2: and_comm") }

    // Test 3: De Morgan — not(P or Q) == (not P) and (not Q)
    var t3 = true
    p = false; q = false
    if !(p || q) != (!p && !q) { t3 = false }
    p = true; q = false
    if !(p || q) != (!p && !q) { t3 = false }
    p = false; q = true
    if !(p || q) != (!p && !q) { t3 = false }
    p = true; q = true
    if !(p || q) != (!p && !q) { t3 = false }
    if t3 { pass = pass + 1; println("PASS T3: de_morgan_or") }
    else { fail = fail + 1; println("FAIL T3: de_morgan_or") }

    // Test 4: De Morgan — not(P and Q) == (not P) or (not Q)
    var t4 = true
    p = false; q = false
    if !(p && q) != (!p || !q) { t4 = false }
    p = true; q = false
    if !(p && q) != (!p || !q) { t4 = false }
    p = false; q = true
    if !(p && q) != (!p || !q) { t4 = false }
    p = true; q = true
    if !(p && q) != (!p || !q) { t4 = false }
    if t4 { pass = pass + 1; println("PASS T4: de_morgan_and") }
    else { fail = fail + 1; println("FAIL T4: de_morgan_and") }

    // Test 5: double negation — not(not P) == P
    var t5 = true
    p = false; if !!p != p { t5 = false }
    p = true;  if !!p != p { t5 = false }
    if t5 { pass = pass + 1; println("PASS T5: double_neg") }
    else { fail = fail + 1; println("FAIL T5: double_neg") }

    // Test 6: absorption — P and (P or Q) == P
    var t6 = true
    p = false; q = false
    if (p && (p || q)) != p { t6 = false }
    p = true; q = false
    if (p && (p || q)) != p { t6 = false }
    p = false; q = true
    if (p && (p || q)) != p { t6 = false }
    p = true; q = true
    if (p && (p || q)) != p { t6 = false }
    if t6 { pass = pass + 1; println("PASS T6: absorption") }
    else { fail = fail + 1; println("FAIL T6: absorption") }

    // Test 7: idempotent — P and P == P
    var t7 = true
    p = false; if (p && p) != p { t7 = false }
    p = true;  if (p && p) != p { t7 = false }
    p = false; if (p || p) != p { t7 = false }
    p = true;  if (p || p) != p { t7 = false }
    if t7 { pass = pass + 1; println("PASS T7: idempotent") }
    else { fail = fail + 1; println("FAIL T7: idempotent") }

    // Test 8: distributive — P and (Q or R) == (P and Q) or (P and R)
    var t8 = true
    var r = false
    p = true; q = true; r = false
    if (p && (q || r)) != ((p && q) || (p && r)) { t8 = false }
    p = true; q = false; r = true
    if (p && (q || r)) != ((p && q) || (p && r)) { t8 = false }
    p = false; q = true; r = true
    if (p && (q || r)) != ((p && q) || (p && r)) { t8 = false }
    if t8 { pass = pass + 1; println("PASS T8: distributive") }
    else { fail = fail + 1; println("FAIL T8: distributive") }

    println("")
    print("Passed: "); print_int(pass); println("")
    print("Failed: "); print_int(fail); println("")

    if fail == 0 { 0 } else { 1 }
}

