//@ run-pass
//@ expect-stdout: V2 PASS

// Vancomycin propagation v2 — upgrade from v1 (KnowledgeF64) to
// stdlib/epistemic/knightian.sio + stdlib/clinical/vancomycin_pbpk.sio.
//
// The v1 test showed conservative GUM propagation. v2 uses the full
// Knightian PBox + 2-compartment population PK + refinement-style
// runtime contracts, and demonstrates:
//
//   1. The standard 1000 mg q12h regimen for an ICU patient with
//      moderate renal function fails the Knightian safety gate
//      (PBox crosses 20 mg/L upper toxicity boundary).
//
//   2. Reducing dose to 750 mg q12h pulls the entire Knightian
//      band into therapeutic [10, 20] mg/L → SAFE.
//
//   3. Contract violations (out-of-range weight) produce a vacuous
//      PBox without panicking the pipeline.
//
// This is the operational unit-test for the M3 milestone.

use clinical::vancomycin_pbpk::*
use epistemic::knightian::*

fn main() -> i32 with IO, Mut, Div, Panic {
    let weight = 78.5
    let crcl = 65.0

    // Pre-TDM (no samples): wide Knightian band, refuse 1000 mg q12h
    let cmin_pre = predict_cmin_knightian(weight, crcl, 1000.0, 12.0, 0)
    let safe_pre = is_safe_dose(&cmin_pre, 10.0, 20.0, 800)

    // Post-TDM (3 trough samples): narrow Knightian band, prescribe approved
    let cmin_post = predict_cmin_knightian(weight, crcl, 1000.0, 12.0, 3)
    let safe_post = is_safe_dose(&cmin_post, 10.0, 20.0, 800)

    // Contract violation: weight 15 kg below allowed [30, 200]
    let cmin_bad = predict_cmin_knightian(15.0, crcl, 1000.0, 12.0, 0)
    let bad_blocked = pb_confidence(&cmin_bad) == 0

    if !safe_pre && safe_post && bad_blocked {
        println("V2 PASS")
    } else {
        if safe_pre {
            println("V2 FAIL: pre-TDM not refused")
        } else if !safe_post {
            println("V2 FAIL: post-TDM not safe")
        } else {
            println("V2 FAIL: contract not enforced")
        }
    }
    0
}

//@ run-pass
// tests/run-pass/viz_controls_modes.sio - Visual IR native control reducers
//
// Expected output:
//   VIZ_CONTROLS_MODES_PASS

use display::canvas::{Canvas, canvas_clear}
use viz::ir::{viz_scene_new, viz_layout_rect, viz_add_control, viz_scene_pointer_down, viz_scene_pointer_move, viz_scene_pointer_update, VIZ_CONTROL_TABS, VIZ_CONTROL_TOGGLE}
use viz::viz_canvas::{viz_canvas_render_scene}
use viz::viz_html::{viz_html_emit_scene}

fn make_canvas(w: i64, h: i64) -> Canvas with Alloc {
    let pix = heap_alloc(w * h * 8) as *mut i64
    Canvas { pixels: pix, width: w, height: h }
}

fn read_px(c: &Canvas, x: i64, y: i64) -> i64 {
    read_i64(c.pixels, y * c.width + x)
}

fn main() with IO, Alloc, Mut, Div {
    var scene = viz_scene_new()
    let tabs = viz_add_control(&!scene, VIZ_CONTROL_TABS, viz_layout_rect(10, 10, 120, 18), 0.0, 0.0, 3.0)
    let toggle = viz_add_control(&!scene, VIZ_CONTROL_TOGGLE, viz_layout_rect(10, 40, 32, 18), 0.0, 0.0, 1.0)
    assert(tabs == 0)
    assert(toggle == 1)

    let hovered = viz_scene_pointer_move(&!scene, 20, 14)
    assert(hovered == tabs)
    assert(scene.hovered_node == tabs)

    let tab_hit = viz_scene_pointer_down(&!scene, 86, 14)
    assert(tab_hit == tabs)
    assert(scene.active_tab == 2)
    assert(scene.nodes[tabs as usize].value == 2.0)
    let tab_drag = viz_scene_pointer_update(&!scene, 129, 14)
    assert(tab_drag == tabs)
    assert(scene.active_tab == 3)
    assert(scene.nodes[tabs as usize].value == 3.0)

    let toggle_on = viz_scene_pointer_down(&!scene, 20, 48)
    assert(toggle_on == toggle)
    assert(scene.nodes[toggle as usize].value == 1.0)
    let toggle_off = viz_scene_pointer_down(&!scene, 20, 48)
    assert(toggle_off == toggle)
    assert(scene.nodes[toggle as usize].value == 0.0)

    var c = make_canvas(160, 80)
    canvas_clear(&!c, 0, 0, 0)
    viz_canvas_render_scene(&scene, &!c)
    assert(read_px(&c, 102, 12) != 0)
    assert(read_px(&c, 10, 40) != 0)
    heap_free(c.pixels as *mut i8)

    viz_html_emit_scene(&scene, 160, 80)
    println("VIZ_CONTROLS_MODES_PASS")
}

